```js
// Animates [data-counter] elements once on first view. 800ms ease-out.
export function counters(root = document) {
  const els = root.querySelectorAll("[data-counter]");
  if (!els.length) return;
  const format = (n) => n.toLocaleString("en-US");
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    els.forEach((el) => { el.textContent = format(+el.dataset.counter); });
    return;
  }
  const io = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (!e.isIntersecting) return;
      io.unobserve(e.target);
      const target = +e.target.dataset.counter;
      const start = performance.now();
      const step = (now) => {
        const p = Math.min((now - start) / 800, 1);
        e.target.textContent = format(Math.round(target * (1 - Math.pow(1 - p, 4)))); // ease-out-quart
        if (p < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    });
  }, { threshold: 0.5 });
  els.forEach((el) => io.observe(el));
}
```

